notes = {
    "hours": "The library opens at 09:00. The library closes at 18:00.",
    "loans": "Students may borrow three books. Books are due after fourteen days.",
}
chunks = [{"id": f"{name}-{i}", "text": sentence.strip() + "."}
    for name, text in notes.items()
    for i, sentence in enumerate(text.split(".")[:-1])]
print(chunks)
assert len(chunks) == 4

import re

def words(text):
    return set(re.findall(r"[a-z0-9]+", text.lower()))

def retrieve(question):
    scored = [(len(words(question) & words(c["text"])), c) for c in chunks]
    score, best = max(scored, key=lambda item: item[0])
    return best if score > 0 else None

hit = retrieve("When does the library open?")
print(hit)
assert hit is not None and hit["id"].startswith("hours-")
